WITH department_totals AS (SELECT dept_id, MAX(salary) AS max_salary, MIN(hire_date) AS min_hire_date FROM employees GROUP BY dept_id) SELECT departments.dept_name, departments.budget, department_totals.max_salary, department_totals.min_hire_date FROM departments LEFT JOIN department_totals ON departments.id = department_totals.dept_id ORDER BY department_totals.max_salary, departments.budget;
